// Valida a assinatura da Meta, ignora repetidos e decide o que fazer com cada mensagem.
// Estado (pausas, ids vistos, contagem) fica no staticData do workflow — só persiste
// em execuções de produção (workflow ATIVO), não no botão "Test".
const crypto = require('crypto');
const cfg = $('Config').first().json;
const state = $getWorkflowStaticData('global');
state.seen = state.seen || [];
state.pausedUntil = state.pausedUntil || {};
state.count = state.count || {};
const now = Date.now();

// --- Assinatura (X-Hub-Signature-256) ---
const req = $('WhatsApp (POST)').first();
let raw = null;
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (e) {
  const b64 = req.binary?.data?.data;
  if (b64 && b64 !== 'filesystem-v2') raw = Buffer.from(b64, 'base64').toString('utf8');
}
if (cfg.APP_SECRET) {
  const got = req.json.headers?.['x-hub-signature-256'] || '';
  if (!raw) throw new Error('Corpo bruto indisponível: não dá pra validar a assinatura. Deixe APP_SECRET vazio no Config ou veja o README.');
  const expected = 'sha256=' + crypto.createHmac('sha256', cfg.APP_SECRET).update(raw).digest('hex');
  if (got.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(got), Buffer.from(expected))) {
    return []; // assinatura inválida: ignora em silêncio
  }
}
const body = raw ? JSON.parse(raw) : req.json.body;

const out = [];
for (const entry of body.entry || []) {
  for (const change of entry.changes || []) {
    const v = change.value || {};

    // Laís respondeu pelo celular (coexistência) → a IA sai dessa conversa.
    if (change.field === 'smb_message_echoes') {
      for (const echo of v.message_echoes || []) {
        state.pausedUntil[echo.to] = now + cfg.HUMAN_PAUSE_HOURS * 3600e3;
      }
      continue;
    }
    if (change.field !== 'messages' || !v.messages) continue;

    for (const msg of v.messages) {
      if (state.seen.includes(msg.id)) continue; // a Meta reenvia eventos
      state.seen.push(msg.id);
      if (state.seen.length > 500) state.seen.splice(0, state.seen.length - 500);

      const from = msg.from;
      if ((state.pausedUntil[from] || 0) > now) continue; // humano no controle

      const name = v.contacts?.find((c) => c.wa_id === from)?.profile?.name || '';
      const base = { from, name, messageId: msg.id };
      state.count[from] = (state.count[from] || 0) + 1;

      if (msg.type !== 'text') {
        // Política do escritório: a IA não abre áudio, foto nem documento (LGPD/OAB).
        out.push({ json: { ...base, action: 'fixed', reply: cfg.ATTACHMENT_MESSAGE, escalate: true, reason: `enviou ${msg.type}` } });
      } else if (state.count[from] > cfg.MAX_USER_MESSAGES) {
        out.push({ json: { ...base, action: 'fixed', reply: cfg.HANDOFF_MESSAGE, escalate: true, reason: 'limite de mensagens da triagem' } });
      } else {
        out.push({ json: { ...base, action: 'ai', text: msg.text.body } });
      }
    }
  }
}
return out;

// Tira a marca [[ESCALATE]] da resposta da IA e decide se passa pra Laís.
const cfg = $('Config').first().json;
return $input.all().map((item, i) => {
  const ctx = $('Processar evento').itemMatching(i).json;
  let reply = String(item.json.output || '').trim();
  const escalate = reply.includes('[[ESCALATE]]');
  reply = reply.replace(/\[\[ESCALATE\]\]/g, '').trim();
  if (!reply) return { json: { ...ctx, reply: cfg.FALLBACK_MESSAGE, escalate: true, reason: 'IA sem resposta' } };
  return { json: { ...ctx, reply, escalate, reason: escalate ? 'triagem concluída / pediu a advogada' : '' } };
});

// Conversa escalada: a IA fica quieta com esse contato até a Laís assumir.
const cfg = $('Config').first().json;
const ctx = $('Tratar resposta').isExecuted ? $('Tratar resposta').item.json : $('Processar evento').item.json;
const state = $getWorkflowStaticData('global');
state.pausedUntil = state.pausedUntil || {};
state.pausedUntil[ctx.from] = Date.now() + cfg.HUMAN_PAUSE_HOURS * 3600e3;
if (state.count) delete state.count[ctx.from];
return { json: ctx };
